from _lib import File
F=File('pre2020_deep5','o-d5','Deepening pass 5 for pre-2020 motocross models: 2011-2013, 2015 and 2019 shootout verdicts with tester fixes, the 2018 350 comparison and the 2015 250 two-stroke shootout (knowledge push 2026-11)','KTM',['450 SX-F'],list(range(2011,2020)))
R=F.R; K='KTM'; Q='Husqvarna'; H='Honda'; Y='Yamaha'; W='Kawasaki'; M='magazine'
T='shootout verdict and fixes'
def S(src,y,mk,md,st,v={},dom='chassis',topic=T): R(dom,md+' '+str(y)+' '+topic,[md],[y],st,v,'TUNER',src,make=mk)
s=F.src(M,"Motocross Action - 2013 450 shootout","https://motocrossactionmag.com/mxas-2013-450-four-stroke-shootout-six-2013-motocross-bikes-walked-into-mxas-o-k-corral-but-only-one-walked-out-plus-video","2013")
S(s,2013,W,'KX450',"A magazine crew ranked the 2013 KX450F first of six: 55.05 hp at 9,000 rpm and 239 lb, with a strong, well-delivered powerband, launch control, adjustable footpegs and plug-in maps. Against it: quirky handling, weak brakes, a loud muffler, a doubtful clutch and a bulky feel.",{'rank':'1 of 6','peak_hp':55.05,'peak_rpm':9000,'weight_lb':239})
S(s,2013,K,'450 SX-F',"A magazine crew ranked the 2013 450 SX-F second of six: 56.95 hp at 9,400 rpm and 240 lb, with the most power over the broadest range and the best brakes, clutch, handling, shifting and starting. The stock WP fork and shock were its weak point and the shock preload ring does not hold a true setting.",{'rank':'2 of 6','peak_hp':56.95,'peak_rpm':9400,'weight_lb':240})
S(s,2013,H,'CRF450R',"A magazine crew ranked the redesigned 2013 CRF450R fourth of six: 51.55 hp at 8,900 rpm, the lowest in the test, at 234 lb. It was the easiest bike to use, with handling and clutch improved over the 2009-2012 bikes, but the power falls off early and is flat by 8,200 rpm.",{'rank':'4 of 6','peak_hp':51.55,'peak_rpm':8900,'weight_lb':234})
S(s,2013,Y,'YZ450F',"A magazine crew ranked the 2013 YZ450F fifth of six: 55.24 hp at 9,100 rpm and 238 lb, with the top-rated fork and shock and very good durability. The powerband is disjointed, turn-in is flawed, the radiator wings are wide and the airbox is noisy.",{'rank':'5 of 6','peak_hp':55.24,'peak_rpm':9100,'weight_lb':238})
s=F.src(M,"Motocross Action - 2012 450 shootout","https://motocrossactionmag.com/motocross-actions-2012-450-shootout-we-tell-you-the-things-that-everyone-else-pussyfoots-around","2012")
S(s,2012,K,'450 SX-F',"A magazine crew ranked the 2012 450 SX-F second of six at 243 lb: electric start, a self-adjusting hydraulic clutch with the new diaphragm spring, smooth carburetted delivery and strong brakes. The bars are low, the shock preload ring is weak and the fuel cap is hard to use.",{'rank':'2 of 6','weight_lb':243})
S(s,2012,Y,'YZ450F',"A magazine crew ranked the 2012 YZ450F fourth of six at 238 lb: class-leading suspension, the most reliable bike in the test and a handheld tuner for the mapping. The top end is flat, the airbox is complicated and noisy, the tank is wide and the side panels break.",{'rank':'4 of 6','weight_lb':238})
S(s,2012,H,'CRF450R',"A magazine crew ranked the 2012 CRF450R fifth of six: the lightest at 231 lb, with comfortable ergonomics and a steering damper, but several horsepower down on its rivals with a flat top end, a four-spring clutch they rated nearly useless, a twitchy front end in rough sections and gearing that is too tall.",{'rank':'5 of 6','weight_lb':231})
S(s,2012,K,'350 SX-F',"A magazine crew ranked the 2012 350 SX-F last of six in their 450-class shootout, where it was measured against full 450s.",{'rank':'6 of 6'})
s=F.src(M,"Motocross Action - 2011 450 shootout","https://motocrossactionmag.com/motocross-actions-2011-450-shootout-we-dont-care-what-bike-you-buy-but-we-dont-want-you-to-make-an-uninformed-decision","2011")
S(s,2011,K,'450 SX-F',"A magazine crew ranked the 2011 450 SX-F first of six: the broadest, easiest powerband, the best clutch, standout brakes, neutral handling and electric start. The understeer of earlier chassis was gone and they listed no significant flaws.",{'rank':'1 of 6'})
S(s,2011,Y,'YZ450F',"A magazine crew ranked the 2011 YZ450F third of six: the best suspension and shifting and strong reliability, a safe choice, but with an engine they called acceptable and no more, on a bike virtually unchanged from 2010.",{'rank':'3 of 6'})
S(s,2011,K,'350 SX-F',"A magazine crew ranked the 2011 350 SX-F fifth of six against 450s. Its handling was rated very, very good, but it is sluggish until about 9,000 rpm, peaks at 12,200 rpm, gives away about 10 hp to a 450 in the midrange and is only five pounds lighter than the 450 SX-F. The suspension is too soft: they recommended the 450 SX-F's fork and shock.",{'rank':'5 of 6','peak_rpm':12200,'midrange_deficit_hp':'about 10 vs a 450'})
S(s,2011,H,'CRF450R',"A magazine crew ranked the 2011 CRF450R last of six: light, with a pleasant, mellow powerband, but a clutch they rated useless, handling that oversteers and wanders, and suspension that is stiff at the rear and soft at the front.",{'rank':'6 of 6'})
s=F.src(M,"Motocross Action - 2012 250 shootout","https://motocrossactionmag.com/mxas-2012-250-four-stroke-shootout-our-brutal-honest-opinions-of-this-years-250-class/","2012")
S(s,2012,H,'CRF250R',"A magazine crew ranked the 2012 CRF250R fourth of five: 38.44 hp at 11,000 rpm, 222 lb, $7,420, with a strong midrange and a new linkage that settles the rear. The frame geometry brings oversteer and headshake, the forks dive under braking, the springs are too soft for riders over 165 lb and the exhaust holds back the top end.",{'rank':'4 of 5','peak_hp':38.44,'peak_rpm':11000,'weight_lb':222,'msrp_usd':7420,'soft_over_lb':165})
S(s,2012,Y,'YZ250F',"A magazine crew ranked the 2012 YZ250F third of five: 37.13 hp at 11,500 rpm, 218 lb and $7,250, with the best suspension in the class, first for durability and a stable, forgiving chassis. The engine is a low-to-mid design and the only carburetted one in the class; they called it sluggish.",{'rank':'3 of 5','peak_hp':37.13,'peak_rpm':11500,'weight_lb':218,'msrp_usd':7250})
S(s,2012,K,'250 SX-F',"A magazine crew ranked the 2012 250 SX-F last of five: 35.52 hp at 10,800 rpm, the lowest, at 231 lb, the heaviest, and $7,699. It had the best brakes and clutch and handles precisely once set up. To fix the harsh fork and odd spring rates they raised the shock spring from 5.1 to 5.4 kg/mm and drained some fork oil.",{'rank':'5 of 5','peak_hp':35.52,'peak_rpm':10800,'weight_lb':231,'msrp_usd':7699,'shock_spring':'5.4 kg/mm (stock 5.1)'})
s=F.src(M,"Motocross Action - 2015 250 shootout","https://motocrossactionmag.com/2015-mxa-250-four-stroke-shootout-the-results-are-in-the-winner-is","2015")
S(s,2015,Y,'YZ250F',"A magazine crew ranked the 2015 YZ250F first of six: coil-spring suspension, a versatile engine, strong all-round handling and durability. It has the weakest front brake in the class, feels loose in flat turns and testers swapped the stock bar bend.",{'rank':'1 of 6'})
S(s,2015,W,'KX250',"A magazine crew ranked the 2015 KX250F second of six on the broadest usable power in the class. It understeers and the shock wallows in corners (different offset clamps and a longer link arm), it resists shifting under load and the clutch does not last like the hydraulic ones (stiffer springs). Use the white coupler.",{'rank':'2 of 6','coupler':'white'})
S(s,2015,H,'CRF250R',"A magazine crew ranked the 2015 CRF250R third of six: good air forks once set, comfortable ergonomics and a progressive front brake, but about 5 hp down on the class leaders, nervous at high speed and with a soft, fading clutch. Setup: 105 mm of sag with the forks lowered in the clamps; heavier riders 100 mm and a quarter turn more high-speed compression.",{'rank':'3 of 6','sag_mm':'105 (100 for heavier riders)','hsc':'+1/4 turn for heavier riders'},'setups')
S(s,2015,Q,'FC 250',"A magazine crew ranked the 2015 FC 250 fifth of six despite more than 43 hp, a hydraulic clutch, a strong front brake and a two-position map switch. The airbox dulls throttle response, the suspension stays stiff and the power is all on top. Their fixes: drain 10 cc from each fork leg, drill the airbox cover (and clean the filter more often), raise the fork legs 15 mm and run 105 mm of sag.",{'rank':'5 of 6','fork_oil':'-10 cc','fork_height_mm':15,'sag_mm':105},'setups')
S(s,2015,K,'250 SX-F',"A magazine crew ranked the 2015 250 SX-F last of six: it has a hydraulic clutch, the best front brake, electric start and reliability, but poor drive out of corners, a powerband too high in the revs and forks too stiff to move. Use fork height to balance the chassis and lower the fork oil 10 cc if it feels harsh.",{'rank':'6 of 6','fork_oil':'-10 cc if harsh'})
s=F.src(M,"Motocross Action - 2019 250 shootout","https://motocrossactionmag.com/mxa-shootout-the-real-2019-250-four-stroke-shootout","2019")
S(s,2019,Y,'YZ250F',"A magazine crew ranked the new 2019 YZ250F first: an easy, usable powerband, coil-spring suspension that is plush early and resists bottoming, and a durable build. At 228 lb it is heavy, feels it at turn-in and is the widest bike in the class. The free phone app changes the maps.",{'rank':1,'weight_lb':228})
S(s,2019,K,'250 SX-F',"In a magazine's 2019 250 shootout the 250 SX-F made the most power, 42.65 hp at 13,800 rpm, and was the lightest at 219 lb, with the best brakes, clutch, shifting and front-end grip. Its power is mellower than 2018, the chassis and suspension are stiffer and the airbox is restricted; it suits fast riders better than average ones.",{'peak_hp':42.65,'peak_rpm':13800,'weight_lb':219})
S(s,2019,Q,'FC 250',"In a magazine's 2019 250 shootout the FC 250 made 42.53 hp at 219 lb and $9,099, the dearest in the class. The plastic airbox is restrictive and it lost power against the 2016 engine: drill the airbox cover. Perforating the muffler's backfire screen also helps but the screen may then burn through.",{'peak_hp':42.53,'weight_lb':219,'msrp_usd':9099})
S(s,2019,H,'CRF250R',"In a magazine's 2019 250 shootout the CRF250R made 42.40 hp at peak but was down as much as 4 hp from 7,000 to 10,000 rpm, so it is sluggish low to mid, hard on clutches and at its worst on tight tracks. The chassis and suspension are plush and comfortable; the fork is soft and can bottom for heavy or fast riders.",{'peak_hp':42.40,'mid_deficit_hp':'up to 4 from 7,000-10,000 rpm'})
S(s,2019,W,'KX250',"A magazine crew ranked the 2019 KX250 fifth: the best bottom-end in the class, slim, precise and the most adjustable, at $7,749, the cheapest. The top end is flat, the clutch wears (heavier springs or a complete aftermarket clutch), the fork is harsh mid-stroke as on the 2018, and there is no electric start.",{'rank':5,'msrp_usd':7749})
s=F.src(M,"Motocross Action - 2018 350 shootout: FC350 versus 350SXF","https://motocrossactionmag.com/2018-mxa-350-shootout-husqvarna-fc350-versus-ktm-350sxf","2018")
R('identity','FC 350 against 350 SX-F (2018): every difference',['FC 350'],[2018],"The 2018 FC 350 and 350 SX-F both make 54 hp at 13,400 rpm and share forks and shock. The Husqvarna differs in its sealed plastic airbox with no vents, composite subframe, a baffled muffler, Magura clutch hydraulics (Brembo on the KTM), different bars, rims and brake discs, and a seat that is longer, thinner and 5 mm lower with about half the foam. It is two pounds heavier. Its low-end is muted and its delivery steadier and more metered; testers found it plusher and better handling, and some veterans preferred it in ruts and off-cambers.",{'peak_hp':54,'peak_rpm':13400,'weight_vs_ktm_lb':'+2'},'OEM',s,make=Q)
R('engine_mods','FC 350 2018: making it run like the KTM',['FC 350'],[2018],"Tester fixes for the 2018 FC 350: cut away part of the right side of the airbox and drill the left cover; replace the baffled muffler with the unrestricted FC 250 muffler or a slip-on; fit the other Austrian brand's slave piston and O-ring to cure the clutch slave seal failures; thread-lock the rear sprocket bolts and check the spokes beside the rim lock before each moto. Husqvarna riders often gear down two teeth at the rear.",{'gearing':'+2 rear teeth'},'TUNER',s,make=Q)
R('chassis','350 SX-F 2018 against the FC 350',['350 SX-F'],[2018],"In a magazine comparison the 2018 350 SX-F beat the FC 350: 54 hp at 13,400 rpm with snappier throttle response from its vented airbox and straight-through muffler, two pounds lighter, and without the Husqvarna's clutch slave seal risk. It took the power, brakes and clutch categories; the Husqvarna took handling and wheels. KTM racers typically add one tooth at the rear. Thread-lock the sprocket bolts and check the spokes next to the rim lock before each moto.",{'peak_hp':54,'peak_rpm':13400,'gearing':'+1 rear tooth'},'TUNER',s,make=K)
s=F.src(M,"Motocross Action - 2015 250 two-stroke shootout","https://motocrossactionmag.com/2015-mxa-250-two-stroke-shootouthusqvarna-tc250-vs-ktm-250sx-vs-yamaha-yz250/","2015")
S(s,2015,Y,'YZ250',"A magazine crew narrowly ranked the 2015 YZ250 first of three 250 two-strokes on the balance of suspension, power delivery, comfort and reliability, even though it was the weakest on the dyno, the slowest off the line and had the weakest brakes. Stock jetting runs clean on pump fuel and changes tend to make it lean. Raising the fork in the clamps with about 107 mm of sag helped cornering at the cost of high-speed stability. The clutch needed frequent adjustment.",{'rank':'1 of 3','sag_mm':'about 107'})
S(s,2015,K,'250 SX',"In a magazine's 2015 250 two-stroke shootout the 250 SX had the strongest dyno numbers, peaking at 8,400 rpm, and the best holeshot, with a strong hydraulic clutch and brakes. The power drops quickly after the peak, so it is short-shifted, it vibrates the most, it ran rough on 91-octane pump fuel until rejetted, and the fork and shock are hard to balance.",{'peak_rpm':8400})
S(s,2015,Q,'TC 250',"In a magazine's 2015 250 two-stroke shootout the TC 250 cornered best of the three, with a smooth powerband from its sealed airbox, but it lacks the KTM's midrange punch, the suspension is hard to balance and riders were less confident on big jumps. The aggressive map (setting two) worked best. Against the 250 SX it has wider, curved bars, a slipperier seat and less vibration.",{'best_map':'2 (aggressive)'})
if __name__=='__main__': F.write()
